117	function CopyButton({ text }: { text: string }) {
118	  const [copied, setCopied] = useState(false);
119	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
120	
121	  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);
122	
123	  const handleCopy = async () => {
124	    if (timerRef.current) clearTimeout(timerRef.current);
125	    try {
126	      await navigator.clipboard.writeText(text);
127	    } catch {
128	      const textarea = document.createElement("textarea");
129	      textarea.value = text;
130	      document.body.appendChild(textarea);
131	      textarea.select();
132	      document.execCommand("copy");
133	      document.body.removeChild(textarea);
134	    }
135	    setCopied(true);
136	    timerRef.current = setTimeout(() => setCopied(false), 2000);
137	  };
138	
139	  return (
140	    <TooltipProvider delayDuration={200}>
141	      <Tooltip>
142	        <TooltipTrigger asChild>
143	          <button
144	            onClick={handleCopy}
145	            className={cn(
146	              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all",
147	              copied
148	                ? "bg-green-50 text-green-600 border border-green-200"
149	                : "bg-card/80 text-slate-500 border border-border/50 hover:bg-muted/40 hover:text-foreground"
150	            )}
151	          >
152	            {copied ? (
153	              <><Check className="h-3 w-3" />Copied</>
154	            ) : (
155	              <><Copy className="h-3 w-3" />Copy</>
156	            )}
157	          </button>
158	        </TooltipTrigger>
159	        <TooltipContent side="top">
160	          <p>{copied ? "Copied to clipboard!" : "Copy AI suggestion"}</p>
161	        </TooltipContent>
162	      </Tooltip>
163	    </TooltipProvider>
164	  );
165	}
